<?php
declare(strict_types=1);
require_once __DIR__ . '/data.php';
function h(string $v): string { return htmlspecialchars($v,ENT_QUOTES,'UTF-8'); }
$error=''; $items=[];
try { $items=reddottBlogVideos(); } catch(Throwable $e) { error_log('Reddott Films blogs index: '.$e->getMessage()); $error=$e->getMessage(); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reddott Films Blog — Video Stories & Insights</title><meta name="description" content="Reddott Films video companion articles, behind-the-video notes and useful context from the official channel."><style>body{margin:0;background:#0b0d12;color:#f5f7fb;font-family:Arial,sans-serif}.wrap{width:min(1100px,calc(100% - 32px));margin:36px auto}.hero,.card{background:#151922;border:1px solid #2a3140;border-radius:18px;padding:24px;margin-bottom:18px}.muted{color:#aeb7c6;line-height:1.65}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}.post{background:#11151d;border:1px solid #2a3140;border-radius:16px;overflow:hidden}.post img{width:100%;aspect-ratio:16/9;object-fit:cover}.post .body{padding:18px}.post h2{font-size:20px;line-height:1.35;margin:0 0 10px}.post a{color:#fff;text-decoration:none}.meta{font-size:12px;color:#8994a7;margin-bottom:12px}.btn{display:inline-block;background:#e11d48;color:#fff;padding:10px 14px;border-radius:9px;margin-top:8px}.error{border-color:#8b1e3f;color:#ffd5df}footer{color:#8994a7;font-size:13px;padding:20px 0}footer a{color:#fff;margin-right:14px}</style></head><body><main class="wrap"><section class="hero"><h1>Reddott Films Blog</h1><p class="muted">A companion space for the official Reddott Films YouTube channel. Each article is tied to a real video and adds context rather than simply reproducing the video page.</p><a class="btn" href="/reddott-films.php">Reddott Films</a></section><?php if($error):?><div class="card error">Unable to load the current YouTube library. Please try again later.</div><?php endif;?><section class="grid"><?php foreach($items as $v): $desc=trim((string)$v['description']); if(strlen($desc)<240) continue; $url='/Reddott-films/blogs/'.rawurlencode(reddottBlogSlug((string)$v['title'])).'/'.rawurlencode((string)$v['id']).'/';?><article class="post"><?php if($v['thumb']!==''):?><img src="<?=h((string)$v['thumb'])?>" alt="<?=h((string)$v['title'])?>" loading="lazy"><?php endif;?><div class="body"><div class="meta">Reddott Films · <?=h(substr((string)$v['published'],0,10))?></div><h2><a href="<?=h($url)?>"><?=h((string)$v['title'])?></a></h2><p class="muted"><?=h(mb_substr(preg_replace('/\s+/',' ',$desc) ?? '',0,180))?><?=mb_strlen($desc)>180?'…':''?></p><a class="btn" href="<?=h($url)?>">Read the article</a></div></article><?php endforeach;?></section><footer><a href="/privacy-policy.php">Privacy</a><a href="/terms.php">Terms</a><a href="/reddott-films.php">Reddott Films</a><p>Low-information video records are intentionally not listed as articles until they have enough original editorial context.</p></footer></main></body></html>
